INSERT INTO public.maxims (
  id, latin_phrase, indonesian_meaning, literal_translation,
  pronunciation_guide, legal_fields, legal_meaning, history,
  is_active, status, difficulty, version_number, data,
  created_at, updated_at
) VALUES (
  'audiatur-et-altera-pars',
  'Audiatur Et Altera Pars',
  'Asas bahwa setiap pihak dalam suatu sengketa berhak untuk didengar, memberikan keterangan, dan membela diri sebelum keputusan diambil',
  'Hendaklah pihak lainnya juga didengar',
  '/au.diˈa.tur et ˈal.te.ra pars/',
  ARRAY['acara','pidana','administrasi'],
  'Audiatur Et Altera Pars adalah sebuah maksim hukum Latin yang berarti "hendaklah pihak lainnya juga didengar." Asas ini menetapkan bahwa tidak ada seorang pun boleh dihukum, dijatuhi sanksi, atau diputus haknya tanpa terlebih dahulu diberikan kesempatan untuk menyampaikan pembelaan, keterangan, atau argumennya. Dalam konteks peradilan, ini berarti hakim wajib mendengarkan kedua belah pihak (penggugat dan tergugat, atau jaksa dan terdakwa) secara seimbang sebelum menjatuhkan putusan.

Fungsi utama dari asas ini adalah mencegah kesewenang-wenangan dan memastikan objektivitas keputusan. Dengan mendengarkan kedua sisi cerita, pengambil keputusan (hakim atau pejabat administrasi) dapat memperoleh gambaran yang utuh dan adil mengenai fakta perkara. Asas ini juga berfungsi sebagai bentuk penghormatan terhadap martabat manusia sebagai subjek hukum yang memiliki hak untuk bersuara dalam proses yang menentukan nasib hukumnya.

Ruang lingkup penerapan asas ini sangat luas, mencakup seluruh ranah hukum: pidana, perdata, tata usaha negara, hingga disiplin kepegawaian. Setiap proses yang berpotensi merugikan hak seseorang harus mendahulukan prinsip mendengar kedua belah pihak. Pelanggaran terhadap asas ini dapat menjadi alasan batalnya suatu putusan atau keputusan administratif.',
  'Sejarah asas Audiatur Et Altera Pars dapat ditelusuri melalui tahapan berikut:

Hukum Romawi Kuno: Prinsip dasar bahwa kedua pihak harus didengar sudah dikenal dalam prosedur Romawi kuno. Praetor (hakim Romawi) berkewajiban memberikan kesempatan kepada kedua pihak untuk menyajikan bukti, meskipun belum dirumuskan dalam maksim Latin yang persis seperti sekarang.

Hukum Kanonik (Abad Pertengahan): Gereja Katolik mengembangkan prinsip ini secara rigor dalam proses pengadilan gereja. Paus Innosensius III menegaskan bahwa keputusan yang diambil tanpa mendengar pihak terdakwa adalah batal demi hukum. Ini menjadi fondasi kuat bagi hukum administrasi modern.

Inggris (Common Law): Di Inggris, asas ini berkembang menjadi salah satu pilar Natural Justice, yaitu the right to a fair hearing. Kasus-kasus abad ke-17 dan 18 memperkuat bahwa bahkan raja atau parlemen tidak boleh mencabut hak seseorang tanpa proses mendengar yang adil.

Belanda dan Indonesia: Belanda mengadopsi asas ini dalam Wetboek van Burgerlijke Rechtsvordering dan Wetboek van Strafvordering. Saat Indonesia menyusun KUHAP (1981) dan UU Kekuasaan Kehakiman, asas ini diintegrasikan sebagai hak fundamental terdakwa dan pihak berperkara untuk didengar keterangannya di sidang pengadilan.',
  true,
  'stable',
  'dasar',
  1,
  '{"synonyms":["Asas Mendengar Kedua Belah Pihak","Right to be Heard","Due Process of Law"],"usedIn":["Indonesia","Inggris","Amerika Serikat","Belanda","negara-negara demokratis lainnya"],"classification":{"legalBranch":"Hukum Acara (Procedural Law), Hukum Tata Negara, dan Hukum Hak Asasi Manusia","nature":"Imperatif","applicationLevel":"Nasional dan Internasional","traditionSource":"Hukum Romawi, Hukum Kanonik, dan prinsip Natural Justice dari Inggris"},"applicabilityStatus":{"validInIndonesia":true,"validInternationally":true,"recognizedByDoctrine":true,"codified":true,"notes":"Dijamin dalam Pasal 28D ayat (1) UUD 1945, KUHAP, UU No. 48 Tahun 2009, dan ICCPR Pasal 14"},"wordByWord":[{"word":"Audiatur","meaning":"Hendaklah didengar, biarlah didengar"},{"word":"Et","meaning":"Dan, juga"},{"word":"Altera","meaning":"Yang lain, pihak satunya"},{"word":"Pars","meaning":"Bagian, pihak"}],"wordByWordExtended":[{"word":"Audiatur","latinForm":"Audire (verba)","partOfSpeech":"Verba (Subjungtif Pasif, Orang ke-3 Tunggal)","meaning":"Hendaklah didengar, biarlah didengar"},{"word":"Et","latinForm":"Et","partOfSpeech":"Konjungsi","meaning":"Dan, juga"},{"word":"Altera","latinForm":"Alter, -a, -um","partOfSpeech":"Adjektiva (Feminin, Nominatif)","meaning":"Yang lain, pihak satunya"},{"word":"Pars","latinForm":"Pars, partis (f)","partOfSpeech":"Nomina (Nominatif)","meaning":"Bagian, pihak"}],"etymologyNotes":"Kalimat ini menggunakan modus Subjungtif Pasif (Audiatur) yang menyatakan sebuah harapan, perintah halus, atau keharusan normatif (\"hendaklah...\"). Et Altera Pars bertindak sebagai subjek pasif (\"pihak lainnya juga\"). Secara harfiah, frasa ini adalah seruan prosedural: \"Biarlah pihak lainnya juga didengar.\" Ini menekankan bahwa mendengar satu pihak saja (audiatur et una pars) adalah ketidakadilan.","philosophicalMeaning":{"origin":"Asas ini berakar pada filosofi keadilan alamiah (natural justice) dan etika deliberatif. Manusia cenderung bias jika hanya mendengar satu versi cerita. Dengan mewajibkan mendengar pihak lain, asas ini memaksa pengambil keputusan untuk melihat masalah dari berbagai sudut pandang.","justiceValue":"Keadilan bukan hanya tentang hasil akhir, tetapi tentang proses yang adil. Seseorang mungkin menerima kekalahan dalam sengketa, asalkan ia merasa telah didengar dan diperlakukan dengan hormat selama proses berlangsung (Keadilan Prosedural).","romanThought":"Prinsip dasar bahwa kedua pihak harus didengar sudah dikenal dalam prosedur Romawi kuno. Praetor berkewajiban memberikan kesempatan kepada kedua pihak untuk menyajikan bukti.","modernRelevance":"Keputusan yang diambil setelah mendengar kedua belah pihak memiliki legitimasi moral dan sosial yang lebih tinggi. Masyarakat akan lebih menerima putusan yang lahir dari proses dialogis yang adil."},"historyTimeline":[{"era":"Hukum Romawi Kuno","period":"Romawi Kuno","description":"Praetor berkewajiban memberikan kesempatan kepada kedua pihak untuk menyajikan bukti, meskipun belum ada rumusan formal."},{"era":"Hukum Kanonik","period":"Abad Pertengahan","description":"Paus Innosensius III menegaskan bahwa keputusan tanpa mendengar pihak terdakwa adalah batal demi hukum."},{"era":"Inggris (Common Law)","period":"Abad ke-17–18","description":"Asas ini berkembang menjadi pilar Natural Justice, yaitu the right to a fair hearing. Bahkan raja tidak boleh mencabut hak seseorang tanpa proses mendengar."},{"era":"Belanda dan Indonesia","period":"Abad ke-19–20","description":"Belanda mengadopsi dalam Wetboek van Burgerlijke Rechtsvordering. Indonesia mengintegrasikannya dalam KUHAP (1981) dan UU Kekuasaan Kehakiman."}],"doctrineDevelopment":[{"era":"Doktrin Formalistik Klasik","description":"Fokus hanya pada apakah pihak tersebut secara fisik hadir dan diberi kesempatan bicara. Sekadar kehadiran dianggap cukup."},{"era":"Doktrin Effective Hearing","description":"Kesempatan mendengar haruslah \"efektif\": pihak diberi waktu cukup, akses terhadap bukti lawan, dan bantuan penasihat hukum jika diperlukan."},{"era":"Doktrin Equality of Arms","description":"Dikembangkan dalam hukum pidana dan HAM internasional. Jaksa dan terdakwa harus memiliki kesempatan seimbang untuk menyajikan kasus. Negara wajib menyediakan bantuan hukum bagi terdakwa miskin."},{"era":"Doktrin Administratif","description":"Dalam hukum administrasi, pejabat tidak boleh bertindak sepihak. Sebelum mencabut izin atau menjatuhkan sanksi, harus ada teguran dan kesempatan membela diri."}],"elements":["Adanya Sengketa atau Proses Pengambilan Keputusan: Harus ada situasi di mana hak atau kepentingan seseorang sedang dipertimbangkan atau diancam.","Identifikasi Pihak yang Terkena Dampak: Pihak yang berpotensi dirugikan oleh keputusan harus diketahui dan dipanggil.","Pemberitahuan yang Cukup (Notice): Pihak tersebut harus diberitahu secara jelas tentang tuduhan, dalil, atau rencana keputusan yang akan diambil.","Kesempatan untuk Merespon (Opportunity to be Heard): Pihak tersebut harus diberi waktu dan wadah (sidang, rapat, surat-menyurat) untuk menyampaikan bantahan, bukti, atau argumen.","Pertimbangan oleh Pengambil Keputusan: Apa yang disampaikan pihak tersebut harus benar-benar dipertimbangkan dalam pengambilan keputusan akhir, bukan sekadar didengar lalu diabaikan."],"conditions":["Pemberitahuan yang Jelas dan Tepat Waktu: Pihak harus tahu kapan, di mana, dan apa yang akan dibahas. Memungkinkan pihak tersebut mempersiapkan pembelaan dengan baik.","Kesempatan yang Nyata, Bukan Semu: Waktu yang diberikan harus memadai, dan hambatan birokrasi tidak boleh menghalangi penyampaian pendapat.","Ketidakberpihakan Pengambil Keputusan: Hakim atau pejabat yang mendengar harus netral (berkaitan dengan Nemo Judex In Causa Sua)."],"exceptions":["Keadaan Darurat Mendesak: Dalam situasi darurat yang mengancam keselamatan publik, pemerintah dapat mengambil keputusan cepat, namun harus ada mekanisme tinjauan pasca-keputusan.","Tindakan Konservatoir: Pengadilan dapat mengeluarkan sita jaminan (conservatoir beslag) tanpa mendengar tergugat terlebih dahulu untuk mencegah penghilangan aset, namun tergugat tetap berhak mengajukan keberatan setelahnya.","Keamanan Negara: Dalam kasus tertentu yang menyangkut rahasia negara tingkat tinggi, proses mendengar mungkin dibatasi, namun tetap harus ada mekanisme pengawasan internal yang ketat."],"scope":{"applies":["Sidang pengadilan (pidana, perdata, TUN).","Proses penyelidikan dan penyidikan (hak tersangka untuk didampingi penasihat hukum dan memberikan keterangan).","Rapat dewan direksi atau RUPS dalam korporasi.","Proses disiplin kepegawaian negeri maupun swasta.","Pencabutan izin usaha atau lisensi oleh pemerintah."],"doesNotApply":["Tindakan kepolisian yang bersifat preventif segera (misalnya: menghentikan perkelahian di jalan).","Keputusan kebijakan legislatif umum (UU dibuat oleh DPR melalui perwakilan, tidak mendengar setiap warga satu per satu)."]},"legalBasisTable":[{"statute":"UUD 1945","article":"Pasal 28D ayat (1)","relevance":"Jaminan konstitusional atas perlakuan yang adil dan kepastian hukum, yang mencakup hak untuk didengar."},{"statute":"UU No. 48 Tahun 2009","article":"Pasal 5 ayat (1)","relevance":"Kewajiban hakim untuk menggali nilai keadilan, yang mensyaratkan mendengar para pihak secara menyeluruh."},{"statute":"KUHAP","article":"Pasal 50 ayat (1)","relevance":"\"Dalam pemeriksaan pada tingkat penyidikan, tersangka berhak mendapat bantuan hukum sejak saat ia ditangkap atau ditahan.\""},{"statute":"KUHAP","article":"Pasal 154","relevance":"Terdakwa berhak mengajukan saksi dan bukti untuk pembelaannya."},{"statute":"UU No. 5 Tahun 1986","article":"Pasal 53","relevance":"Tentang Pengadilan TUN, menjamin hak gugat bagi mereka yang kepentingannya dirugikan oleh keputusan administrasi."}],"indonesianLegalBasis":"Pasal 28D ayat (1) UUD 1945, KUHAP Pasal 50 dan 154, UU No. 48 Tahun 2009, dan ICCPR Pasal 14 (UU No. 12 Tahun 2005).","indonesianSystemRelation":"Bagi Hakim: wajib memimpin persidangan dengan memberikan kesempatan seluas-luasnya kepada semua pihak untuk bertanya, mengajukan bukti, dan membuat pledoi. Bagi Penyidik: wajib mencatat keterangan tersangka/saksi secara lengkap termasuk bantahan. Bagi Pejabat Administrasi: wajib mengeluarkan surat teguran dan mengundang pihak terkait untuk klarifikasi sebelum mencabut izin atau memberi sanksi.","normativeExamples":["Hukum Acara Pidana: Setelah jaksa membacakan dakwaan, ketua pengadilan wajib menanyakan kepada terdakwa apakah ia mengerti dakwaan dan memberinya kesempatan mengajukan eksepsi (keberatan) sebelum masuk ke pokok perkara.","Hukum Acara Perdata: Gugatan tidak boleh dikabulkan secara verstek jika tergugat hadir. Tergugat wajib diberi kesempatan menjawab gugatan (jawaban tergugat) sebelum penggugat membacakan replik.","Hukum Administrasi Negara: Seorang PNS yang akan dikenai hukuman disiplin berat wajib dipanggil untuk sidang kode etik, berhak membela diri dan menghadirkan saksi pendukung sebelum surat keputusan hukuman diterbitkan."],"practicalExamples":["Sidang Korupsi: Terdakwa korupsi didampingi tim penasihat hukum yang aktif mengajukan pertanyaan kepada saksi-saksi jaksa dan mengajukan bukti alibi. Jika hakim melarang terdakwa bertanya tanpa alasan, itu adalah pelanggaran asas.","Sengketa Tanah: Dalam mediasi atau sidang tanah, kedua pihak yang mengklaim kepemilikan diberi waktu yang sama untuk menunjukkan sertifikat, saksi, dan bukti pembayaran pajak. Hakim tidak boleh langsung percaya pada satu pihak tanpa mendengar penjelasan pihak lain.","Pemecatan Karyawan: Perusahaan tidak boleh memecat karyawan karena dugaan pelanggaran secara langsung. HRD harus memanggil karyawan, menyampaikan tuduhan, dan mendengarkan penjelasannya. Jika tidak, PHK dapat digugat ke PHI sebagai PHK sepihak yang tidak sah."],"jurisprudence":[{"id":"mk-21-2014","courtName":"Mahkamah Konstitusi","caseNumber":"No. 21/PUU-XII/2014","year":2014,"date":"2014","context":"Pengujian UU KPK terkait Hak Tersangka","excerpt":"MK menegaskan bahwa hak tersangka untuk didengar dan didampingi penasihat hukum adalah hak konstitusional yang tidak bisa dikurangi sembarangan.","summary":"Menegaskan landasan konstitusional dari hak untuk didengar dalam proses pidana.","analysis":"Mengukuhkan bahwa Audiatur Et Altera Pars bukan sekadar asas prosedural, melainkan hak konstitusional yang dilindungi Pasal 28D UUD 1945.","sourceUrl":"https://www.mkri.id"},{"id":"ma-123-tun-2015","courtName":"Mahkamah Agung","caseNumber":"No. 123 K/TUN/2015","year":2015,"date":"2015","context":"Sengketa TUN Pencabutan Izin","excerpt":"MA membatalkan keputusan gubernur yang mencabut izin usaha tanpa memberikan kesempatan kepada pengusaha untuk membela diri terlebih dahulu.","summary":"Aplikasi murni Audiatur Et Altera Pars dalam hukum administrasi. Keputusan sepihak dinyatakan batal.","analysis":"Putusan ini menegaskan bahwa setiap keputusan administrasi yang merugikan warga harus didahului proses mendengar, bukan sekadar formalitas.","sourceUrl":"https://www.mahkamahagung.go.id"},{"id":"pt-45-2018","courtName":"Pengadilan Tinggi Jakarta","caseNumber":"No. 45/Pdt.G/2018/PT.Jkt","year":2018,"date":"2018","context":"Sengketa Perdata Wanprestasi","excerpt":"PT membatalkan putusan PN karena tergugat tidak dipanggil secara sah sehingga tidak bisa hadir dan membela diri (verstek yang cacat).","summary":"Menunjukkan bahwa hak untuk hadir dan didengar adalah syarat mutlak sahnya putusan perdata.","analysis":"Pemanggilan yang tidak sah menjadikan seluruh proses cacat formil dan putusan harus dibatalkan.","sourceUrl":"https://www.mahkamahagung.go.id"}],"caseExamples":[],"internationalComparisons":[{"country":"Inggris","status":"Dikenal","description":"Dikenal sebagai Audi Alteram Partem, salah satu dari dua aturan Natural Justice. Pelanggaran terhadap asas ini otomatis membatalkan keputusan (void)."},{"country":"Amerika Serikat","status":"Dikenal","description":"Terkandung dalam Due Process Clause pada Amandemen ke-5 dan ke-14 Konstitusi AS. MA AS secara konsisten membatalkan tindakan pemerintah yang tidak memberikan notice dan hearing yang memadai."},{"country":"Jerman","status":"Dikenal","description":"Anspruch auf rechtliches Gehör (Hak untuk didengar secara hukum) dijamin dalam Pasal 103 Grundgesetz. Pelanggaran adalah alasan banding konstitusional (Verfassungsbeschwerde)."},{"country":"Prancis","status":"Dikenal","description":"Principe du contradictoire (Prinsip kontradiktoral) mewajibkan semua bukti dan argumen saling dipertukarkan dan didiskusikan oleh kedua pihak sebelum hakim memutuskan."},{"country":"Belanda","status":"Dikenal","description":"Diatur dalam Wetboek van Burgerlijke Rechtsvordering dan Wetboek van Strafvordering sebagai hak fundamental para pihak dalam proses peradilan."}],"maximComparisons":[{"maximId":"nemo-judex-in-causa-sua","latinPhrase":"Nemo Judex In Causa Sua","whenUsed":"Pasangan kembar. Audiatur menjamin pihak didengar, Nemo Judex menjamin hakim netral. Keduanya adalah pilar Natural Justice."},{"maximId":"in-dubio-pro-reo","latinPhrase":"In Dubio Pro Reo","whenUsed":"Audiatur adalah prosesnya (mendengar), In Dubio adalah aturan keputusannya jika setelah mendengar masih ragu."},{"maximId":"due-process","latinPhrase":"Due Process of Law","whenUsed":"Audiatur Et Altera Pars adalah komponen inti dari Due Process. Tanpa mendengar, tidak ada proses yang adil."},{"maximId":"equality-of-arms","latinPhrase":"Equality of Arms","whenUsed":"Turunan modern dari Audiatur. Bukan hanya didengar, tapi didengar dengan kedudukan yang setara (akses bukti, penasihat, dll)."}],"analysis":{"purpose":"Mencegah kesewenang-wenangan, memastikan akurasi fakta, dan memberikan legitimasi pada keputusan.","protectedValues":"Keadilan prosedural, martabat manusia, dan objektivitas.","advantages":"Meningkatkan kualitas keputusan karena berbasis informasi lengkap dari dua sisi. Membangun kepercayaan publik pada institusi hukum.","critique":"Dapat memperlambat proses peradilan atau administrasi karena harus menunggu respons pihak lain. Sering disalahgunakan oleh pihak yang berniat mengulur waktu (delaying tactics).","limitations":"Efektivitasnya bergantung pada kapasitas pihak untuk membela diri. Pihak yang miskin atau tidak berpendidikan mungkin \"didengar\" tetapi tidak mampu membela diri secara efektif tanpa bantuan hukum."},"scholarViews":[{"name":"Prof. Dr. Jimly Asshiddiqie, S.H., M.H.","view":"Hak untuk didengar (right to be heard) adalah elemen esensial dari due process of law dalam negara hukum demokrasi. Tanpa ini, supremasi hukum hanyalah omong kosong.","source":"Hak Asasi Manusia dan Negara Hukum (2006)"},{"name":"Prof. Dr. Andi Hamzah, S.H.","view":"Dalam pemeriksaan tersangka, polisi wajib mencatat segala keterangan, termasuk bantahan. Mengabaikan bantahan tersangka adalah pelanggaran terhadap asas Audiatur Et Altera Pars yang dapat merusak kekuatan bukti di pengadilan.","source":"Asas-Asas Hukum Pidana (2017)"},{"name":"Prof. Dr. Philipus Hadjon, S.H.","view":"Freies Ermessen (diskresi) pejabat tidak boleh lepas dari asas Audiatur Et Altera Pars. Keputusan diskresi yang merugikan warga harus didahului dengan proses mendengar warga tersebut.","source":"Hukum Administrasi Negara (2005)"}],"controversies":[{"title":"Keseimbangan antara Efisiensi dan Keadilan","description":"Dalam kasus-kasus yang sangat kompleks atau melibatkan banyak pihak (misalnya: sengketa lingkungan dengan ribuan korban), mendengar \"semua pihak\" secara individual bisa memakan waktu bertahun-tahun. Muncul perdebatan akademis tentang bagaimana menerapkan asas ini secara kolektif atau representatif tanpa mengorbankan hak individu untuk didengar."},{"title":"Mendengar via Platform Digital","description":"Dalam era digital, muncul pertanyaan apakah \"mendengar\" via email atau platform online sudah memenuhi standar asas ini dibandingkan tatap muka di sidang."}],"commonMistakes":[{"misconception":"\"Asas ini hanya berlaku di pengadilan.\"","fact":"Salah. Asas ini juga berlaku mutlak dalam administrasi negara, korporasi, dan organisasi profesi."},{"misconception":"\"Jika pihak lawan tidak hadir, kita otomatis menang.\"","fact":"Tidak selalu. Dalam perdata, bisa terjadi putusan verstek, tetapi jika panggilan tidak sah, putusan itu bisa digugat ulang. Hak untuk didengar harus difasilitasi dengan panggilan yang sah."},{"misconception":"\"Mendengar artinya setuju dengan pihak tersebut.\"","fact":"Salah. Mendengar adalah kewajiban prosedural untuk mengumpulkan informasi. Keputusan akhir bisa saja tetap merugikan pihak tersebut setelah didengar."}],"faq":[{"question":"Apakah Audiatur Et Altera Pars berlaku dalam arbitrase?","answer":"Ya. Arbitrase juga wajib menerapkan asas ini. Arbiter harus mendengar kedua pihak sebelum memutus sengketa dagang."},{"question":"Bagaimana jika salah satu pihak sengaja tidak mau hadir?","answer":"Jika sudah dipanggil secara sah, proses dapat dilanjutkan (ex parte). Namun pengadilan harus memastikan ketidakhadiran itu adalah pilihan sadar, bukan karena gagal panggil."},{"question":"Apakah hak untuk diam (dalam pidana) melanggar asas ini?","answer":"Tidak. Asas Audiatur berarti negara wajib memberi kesempatan untuk bicara, bukan memaksa bicara. Jika tersangka memilih diam, ia telah menggunakan haknya secara sukarela."},{"question":"Bisakah putusan dibatalkan hanya karena pelanggaran asas ini?","answer":"Ya. Pelanggaran terhadap hak untuk didengar adalah alasan kuat untuk banding, kasasi, atau peninjauan kembali karena merupakan cacat formil yang serius."},{"question":"Apakah media sosial bisa menjadi tempat \"mendengar\" pihak lain?","answer":"Tidak secara hukum. Proses hukum formal memerlukan saluran resmi yang tercatat dan terverifikasi. Opini di media sosial tidak menggantikan hak untuk didengar di pengadilan."}],"maximNotes":"Bukti bahwa asas ini telah dipenuhi adalah Berita Acara Pemeriksaan (BAP) atau Risalah Sidang yang menandatangani bahwa pihak tersebut telah dimintai keterangan. Untuk memastikan asas ini bermakna, kehadiran penasihat hukum sangat krusial agar apa yang \"didengar\" oleh hakim adalah argumen hukum yang tajam.","relatedTerms":[{"term":"Due Process of Law","definition":"Proses Hukum yang Adil — keseluruhan hak prosedural seseorang dalam proses hukum."},{"term":"Natural Justice","definition":"Keadilan Alamiah — prinsip-prinsip fundamental keadilan prosedural dalam Common Law."},{"term":"Nemo Judex In Causa Sua","definition":"Tidak Ada Hakim Dalam Kasusnya Sendiri — pasangan dari Audiatur Et Altera Pars."},{"term":"Right to Fair Trial","definition":"Hak Atas Peradilan yang Adil — hak fundamental dalam sistem peradilan demokratis."},{"term":"Equality of Arms","definition":"Kesamaan Kedudukan — kedua pihak memiliki akses dan kesempatan yang setara."},{"term":"Verstek","definition":"Putusan Tanpa Hadirnya Tergugat — putusan perdata yang dijatuhkan karena tergugat tidak hadir."},{"term":"Ex Parte","definition":"Proses Satu Pihak — proses hukum yang dilakukan tanpa kehadiran pihak lain."},{"term":"Notice and Hearing","definition":"Pemberitahuan dan Pendengaran — dua syarat minimal hak untuk didengar."},{"term":"Procedural Fairness","definition":"Keadilan Prosedural — keadilan dalam proses, bukan hanya hasil."},{"term":"Legal Standing","definition":"Kedudukan Hukum untuk Didengar — syarat seseorang memiliki hak mengajukan gugatan atau pembelaan."}],"relations":[{"id":"in-dubio-pro-reo","latinPhrase":"In Dubio Pro Reo","indonesianMeaning":"Dalam keraguan, menguntungkan terdakwa","relationType":"hierarkis"},{"id":"audi-alteram-partem","latinPhrase":"Audi Alteram Partem","indonesianMeaning":"Dengarkanlah pihak lainnya","relationType":"sinonim"},{"id":"nemo-tenetur","latinPhrase":"Nemo Tenetur Se Ipsum Accusare","indonesianMeaning":"Hak untuk tidak memberatkan diri sendiri","relationType":"terkait"}],"references":{"primary":{"constitutions":["Undang-Undang Dasar Negara Republik Indonesia Tahun 1945, Pasal 28D ayat (1)."],"statutes":["Undang-Undang Nomor 48 Tahun 2009 tentang Kekuasaan Kehakiman.","Kitab Undang-Undang Hukum Acara Pidana (KUHAP), Pasal 50, 154.","Undang-Undang Nomor 12 Tahun 2005 tentang Pengesahan ICCPR, Pasal 14.","Undang-Undang Nomor 5 Tahun 1986 tentang Pengadilan Tata Usaha Negara, Pasal 53."],"rulings":["Putusan Mahkamah Konstitusi No. 21/PUU-XII/2014."]},"secondary":{"books":["Asshiddiqie, Jimly. (2006). Hak Asasi Manusia dan Negara Hukum. Jakarta: Konpress.","Hamzah, Andi. (2017). Asas-Asas Hukum Pidana. Jakarta: Rineka Cipta.","Hadjon, Philipus. (2005). Hukum Administrasi Negara. Jakarta: UI Press.","Reksodiputro, Mardjono. Hukum Acara Pidana Indonesia.","Ridwan H.R. Hukum Administrasi Negara."],"journals":["Jurnal Hukum IUS QUIA IUSTUM. Artikel mengenai \"Implementasi Asas Audiatur Et Altera Pars dalam Putusan PTUN\".","Constitutional Review. Analisis hak atas peradilan yang adil."]},"tertiary":{"encyclopedias":["Mahkamah Konstitusi Republik Indonesia. Putusan No. 21/PUU-XII/2014.","Mahkamah Agung Republik Indonesia. Direktori Putusan."]}},"furtherReading":[{"title":"Hukum Acara Pidana Indonesia","author":"Mardjono Reksodiputro","type":"buku"},{"title":"Hukum Administrasi Negara","author":"Ridwan H.R.","type":"buku"},{"title":"Jurnal Hukum IUS QUIA IUSTUM","author":"Berbagai Penulis","type":"jurnal"},{"title":"Constitutional Review","author":"Mahkamah Konstitusi","type":"jurnal"}],"meta":{"categories":["Asas Hukum","Hukum Acara","Hak Asasi Manusia"],"portals":["Ilmu Hukum","Keadilan Prosedural"],"tags":["Audiatur Et Altera Pars","Hak Untuk Didengar","Due Process","Natural Justice","Pasal 28D UUD 1945","Keadilan Prosedural"]}}'::jsonb,
